INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "僖宗葬靖陵并定庙号", "start_year": 888, "end_year": 888, "time_original": "888年十月辛卯", "dynasty": "唐", "description": "朝廷将惠圣恭定孝皇帝葬于靖陵，定庙号僖宗。", "phases": [], "location_name": "靖陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "16107e76-6431-57b7-a815-a91ba11b490a"}, {"title": "陈敬瑄田令孜备兵拒韦昭度", "start_year": 888, "end_year": 888, "time_original": "888年十月后；具体日未载", "dynasty": "唐", "description": "陈敬瑄、田令孜闻韦昭度将至，整军修城以拒。", "phases": [], "location_name": "成都、西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3ae97e85-4b59-51d7-97d1-2a9de3df1821"}, {"title": "朱珍败时溥于吴康镇", "start_year": 888, "end_year": 888, "time_original": "888年十一月", "dynasty": "唐", "description": "时溥亲率步骑屯吴康镇，与朱珍军交战，被朱珍击败。", "phases": [], "location_name": "吴康镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8b7fad33-b42f-5ae3-afb3-685356e7cb8f"}, {"title": "张友以宿州降朱全忠", "start_year": 888, "end_year": 888, "time_original": "888年十一月；具体日未载", "dynasty": "唐", "description": "朱全忠另遣军攻宿州，刺史张友投降。", "phases": [], "location_name": "宿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1b05ba00-0981-5591-824e-5cc91a9f66f5"}, {"title": "秦宗权别将陷许州执王蕴", "start_year": 888, "end_year": 888, "time_original": "888年十一月丙申", "dynasty": "唐", "description": "秦宗权部将攻陷许州，拘获忠武留后王蕴；《通鉴》记其重新夺取许州。", "phases": [], "location_name": "许州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fc2858ae-959e-5772-b364-6fd90a363e17"}, {"title": "申丛拘秦宗权归朱全忠", "start_year": 888, "end_year": 888, "time_original": "888年十二月", "dynasty": "唐", "description": "蔡州将领申丛拘禁秦宗权，将其折足后归降朱全忠。", "phases": [], "location_name": "蔡州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c02db9cc-9569-582c-a08b-533a897776d4"}, {"title": "朱全忠表申丛蔡州留后", "start_year": 888, "end_year": 888, "time_original": "888年十二月；申丛归降后", "dynasty": "唐", "description": "朱全忠上表请任申丛为蔡州留后。", "phases": [], "location_name": "蔡州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ba36591c-9c79-500c-8b44-d7f6f5e09876"}, {"title": "杨晟昔失兴凤后据文龙成茂", "start_year": null, "end_year": null, "time_original": "此前；具体年未载", "dynasty": "唐", "description": "《通鉴》追叙杨晟失兴、凤后退据文、龙、成、茂四州。", "phases": [], "location_name": "兴州、凤州、文州、龙州、成州、茂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e72f2245-b275-5285-b46d-ac1b6891213b"}, {"title": "田令孜署杨晟威戎军节度使守彭州", "start_year": 888, "end_year": 888, "time_original": "王建攻西川后；具体日未载", "dynasty": "唐", "description": "田令孜因杨晟为其旧将，假其威戎军节度使之号，令守彭州。", "phases": [], "location_name": "彭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5478701d-af94-5217-9178-aeea81627bd2"}, {"title": "王建攻彭州，山行章屯新繁救援", "start_year": 888, "end_year": 888, "time_original": "888年十二月前后；具体日未载", "dynasty": "唐", "description": "王建进攻彭州，陈敬瑄遣眉州刺史山行章率军屯新繁救援。", "phases": [], "location_name": "彭州、新繁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1b8ec016-ba0c-546d-b381-e410e01e07b7"}, {"title": "韦昭度任行营招讨使，王建领永平军", "start_year": 888, "end_year": 888, "time_original": "888年十二月丁亥", "dynasty": "唐", "description": "朝廷命韦昭度为行营招讨使、杨守亮为副、顾彦朗为行军司马；割邛、蜀、黎、雅置永平军，授王建节度使，治邛州并充诸军都指挥使。", "phases": [], "location_name": "西川、邛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "28340c3c-0b54-589c-a322-dc7c310bcb55"}, {"title": "朝廷削陈敬瑄官爵", "start_year": 888, "end_year": 888, "time_original": "888年十二月戊子", "dynasty": "唐", "description": "朝廷削去陈敬瑄官爵。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "dc5fddaf-e0b4-581f-a828-118614de4c2f"}, {"title": "杨守厚攻陷夔州", "start_year": 888, "end_year": 888, "time_original": "888年十二月；具体日未载", "dynasty": "唐", "description": "山南西道节度使杨守厚攻陷夔州。", "phases": [], "location_name": "夔州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9d06ddc8-2b13-554f-9ef3-714023b3af20"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

